{"code": "c=load_corpus(); rows=[]
for q in c:
 if 'smooth_additive' not in q.get('prompt','') or q.get('metric')!='test_ce': continue
 def delta(x):
  T=x['training_steps']; lr=x['lr']; o=x['optimizer']; m=x.get('momentum') or 0
  if o in ('Adam','AdamW','RMSprop'): return lr*T
  if o=='Adagrad': return 2*lr*(T**.5)
  return lr*T/(1-m)/100
 ds=[delta(x) for x in q['choices']]
 # low: max LN + residual; high: min depth, max width, fewer LN, smooth activ unknown
 if min(ds)<.1: pred=max(range(len(ds)),key=lambda i: (sum(q['choices'][i]['layer_norm'] or []),q['choices'][i]['residual']))
 else: pred=min(range(len(ds)),key=lambda i:(q['choices'][i]['depth'],-q['choices'][i]['width'],sum(q['choices'][i]['layer_norm'] or [])))
 gold=[x['letter'] for x in q['choices']].index(q['correct_letter'])
 rows.append((pred==gold,q['question_id'],q['correct_letter'],[round(x,3) for x in ds],pred))
print(len(rows),sum(x[0] for x in rows)); print(rows)"}

