def parse(q):
    parts=re.split(r'### Choice ([A-Z])\n',q)
    Tg=re.search(r'training_steps: (\d+)',parts[0]); T0=int(Tg.group(1)) if Tg else None
    out={}
    for i in range(1,len(parts),2):
        t=parts[i+1]
        g=lambda p: (re.search(p,t).group(1) if re.search(p,t) else None)
        ln=g(r'Layer norm per layer: \[([^\]]*)\]')
        T=g(r'training_steps: (\d+)')
        out[parts[i]]=dict(opt=g(r'Optimizer: (\w+)'),lr=float(g(r'Learning rate: ([\d.e-]+)') or 0),mom=float(g(r'Momentum: ([\d.]+)') or 0),T=int(T) if T else T0,
                          ln=ln.count('True') if ln is not None else None,res=g(r'Residual connections: (\w+)')=='True',typ=g(r'- Type: ([^\n]+)'))
    return out
def delta(ch,fam):
    o=ch['opt'];lr=ch['lr'];T=ch['T'];m=ch['mom']
    if o in('Adam','AdamW','RMSprop'): return lr*T
    if o=='Adagrad': return 2*lr*np.sqrt(T)
    if o=='SGD':
        g=0.01
        if fam=='bigram_lm': g=0.003
        elif 'regression' in fam and m>0: g=0.03
        return lr*T*g/(1-m)
tot=collections.defaultdict(lambda:[0,0,0])
for r in h:
    if r['family']=='bigram_lm': continue
    P=parse(r['question'])
    if any(v['ln'] is None or v['T'] is None for v in P.values()): continue
    s1={k:delta(v,r['family']) for k,v in P.items()}; s2={k:s1[k]*(1+v['ln']+v['res']) for k,v in P.items()}
    if len(set(v['opt'] for v in P.values()))==1 and len(set(v['lr'] for v in P.values()))==1: continue  # arch-only
    if r['task']=='select':
        b1=max(s1,key=s1.get); b2=max(s2,key=s2.get)
        tot['select'][0]+=1; tot['select'][1]+=b1==r['answer']; tot['select'][2]+=b2==r['answer']
        print(r['question_id'],r['family'][:6],'gold',r['answer'],'Δ',b1,'Δ*',b2)
    else:
